package org.apache.commons.math.optimization.fitting;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.analysis.ParametricUnivariateRealFunction;
import org.apache.commons.math.analysis.function.Gaussian;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.NumberIsTooSmallException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.DifferentiableMultivariateVectorialOptimizer;
import org.apache.commons.math.optimization.fitting.CurveFitter;
import org.apache.commons.math.optimization.fitting.WeightedObservedPoint;
import org.apache.commons.math3.fitting.WeightedObservedPoints;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction;
import org.apache.commons.math3.optim.nonlinear.scalar.noderiv.BOBYQAOptimizer;
import org.apache.commons.math3.optim.nonlinear.scalar.noderiv.NelderMeadSimplex;
import org.apache.commons.math3.optim.nonlinear.scalar.noderiv.SimplexOptimizer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GaussianFitter_fit_TriageGen1Test {

    private SimplexOptimizer optimizer;
    private WeightedObservedPoints obsPoints;

    @Before
    public void setUp() {
        // Using a real optimizer as it is required for the internal logic of GaussianFitter
        optimizer = new SimplexOptimizer(1e-10, 1e-12);
        obsPoints = new WeightedObservedPoints();
    }

    /**
     * Tests the fit() method with a standard Gaussian dataset.
     * This ensures the flow from ParameterGuesser through the parametric fit works.
     */
    @Test
    public void testFitSuccess() {
        // Create a synthetic Gaussian distribution: amplitude=1.0, mean=5.0, sigma=1.0
        // We add points around the mean to ensure the fitter can converge
        obsPoints.add(3.0, 0.05);
        obsPoints.add(4.0, 0.24);
        obsPoints.add(5.0, 0.39);
        obsPoints.add(6.0, 0.24);
        obsPoints.add(7.0, 0.05);

        GaussianFitter fitter = new GaussianFitter(optimizer, obsPoints);

        // The fit() method calls ParameterGuesser internally and then calls fit(Gaussian.Parametric, guess)
        double[] result = fitter.fit();

        // Result array order for Gaussian: [amplitude, mean, sigma]
        // We use a delta because optimization is an approximation
        assertEquals(3, result.length);
        assertEquals(1.0, result[0], 0.1); // Amplitude
        assertEquals(5.0, result[1], 0.1); // Mean
        assertEquals(1.0, result[2], 0.1); // Sigma
    }

    /**
     * Tests the fit() method with a very small dataset to check robustness.
     */
    @Test
    public void testFitWithMinimalData() {
        // Minimal points to define a curve
        obsPoints.add(0.0, 0.0);
        obsPoints.add(1.0, 1.0);
        obsPoints.add(2.0, 0.0);

        GaussianFitter fitter = new GaussianFitter(optimizer, obsPoints);
        double[] result = fitter.fit();

        assertEquals(3, result.length);
        // Even with minimal data, the fitter should return a valid array
        // We just check that it doesn't crash and returns finite numbers
        for (double val : result) {
            assertEquals(Double.NaN, Double.isNaN(val) ? 1.0 : 0.0, 0.0);
        }
    }

    /**
     * Tests the fit(double[]) overload to ensure coverage of the complex branch.
     */
    @Test
    public void testFitWithInitialGuess() {
        obsPoints.add(3.0, 0.05);
        obsPoints.add(4.0, 0.24);
        obsPoints.add(5.0, 0.39);
        obsPoints.add(6.0, 0.24);
        obsPoints.add(7.0, 0.05);

        GaussianFitter fitter = new GaussianFitter(optimizer, obsPoints);

        // Provide a specific initial guess: [amplitude, mean, sigma]
        double[] initialGuess = new double[]{0.5, 4.0, 2.0};
        double[] result = fitter.fit(initialGuess);

        assertEquals(3, result.length);
        assertEquals(1.0, result[0], 0.2);
        assertEquals(5.0, result[1], 0.2);
        assertEquals(1.0, result[2], 0.2);
    }
}
